];
export default function Page() {
  return (
    <RechnerSeite
      pfad={PFAD}
      toolId="kommune"
      breadcrumb="Kommunal-Rechner"
      eyebrow="Für Kommunen & Stadtwerke"
      title={
        <>
          Was ein Solarpark <span className="ov-text-gradient-light">Ihrer Gemeinde bringt.</span>
